def attempt(operation, max_attempts):
    if max_attempts < 1:
        raise ValueError('max_attempts must be positive')
    last_error = None
    for _ in range(max_attempts + 1):
        try:
            return operation()
        except RuntimeError as exc:
            last_error = exc
    raise last_error
from app import attempt

def test_budget_is_exact():
    calls=[]
    def fail():
        calls.append(1); raise RuntimeError('no')
    try: attempt(fail, 2)
    except RuntimeError: pass
    assert len(calls) == 2

