from app import attempt

for budget in (1, 2, 5):
    errors = []
    def fail():
        error = RuntimeError('failure')
        errors.append(error)
        raise error
    try:
        attempt(fail, budget)
    except RuntimeError as error:
        assert len(errors) == budget
        assert error is errors[-1]
    else:
        raise AssertionError('Expected failure')

for success_at in (1, 3):
    calls = []
    result = object()
    def succeed():
        calls.append(1)
        if len(calls) < success_at:
            raise RuntimeError('retry')
        return result
    assert attempt(succeed, 3) is result
    assert len(calls) == success_at

for budget in (0, -1):
    calls = []
    try:
        attempt(lambda: calls.append(1), budget)
    except ValueError as error:
        assert str(error) == 'max_attempts must be positive'
        assert not calls
    else:
        raise AssertionError('Expected validation error')

calls = []
error = TypeError('not retryable')
def fail_other():
    calls.append(1)
    raise error
try:
    attempt(fail_other, 3)
except TypeError as caught:
    assert caught is error
    assert len(calls) == 1
else:
    raise AssertionError('Expected TypeError')
print('Additional budget, success, validation, and exception checks passed')
